import{_ as e,c as i,o as l,ah as a,ao as p,ap as t}from"./chunks/framework.Dq2_gudl.js";const f=JSON.parse('{"title":"Pets in Heaven — その子と、天国と、あなたの悲しみ","description":"ペットを亡くしたあなたへ。聖書が動物と永遠、神の顧みについて語っていること。4つのやさしい読みもの。","frontmatter":{"title":"Pets in Heaven — その子と、天国と、あなたの悲しみ","description":"ペットを亡くしたあなたへ。聖書が動物と永遠、神の顧みについて語っていること。4つのやさしい読みもの。"},"headers":[],"relativePath":"ja/pets-in-heaven/index.md","filePath":"ja/pets-in-heaven/index.md"}'),n={name:"ja/pets-in-heaven/index.md"};function o(c,s,r,d,v,h){return l(),i("div",null,[...s[0]||(s[0]=[a('<div class="pl-quote"><p>「その子が逝ってから、本当に知りたかったのは一つだけでした。今、元気でいるのかな。また会えるのかな」</p><p class="pl-quote-soft">聖書はすべての問いに一文で答えてはくれません。それでも、いちばん暗い夜にも希望が見えるだけの光を与えてくれます。</p></div><section class="pl-section"><h2>はじめに</h2><p class="pl-lead">ここは「早く立ち直りなさい」と急かす場所ではありません。この4つの読みものは、まだその子を恋しく思っているあなたのためのものです。</p><p>動物の伴侶を失うことは、とても特別な悲しみです。人は「たかが犬でしょ」「また飼えばいい」と言います。でも、あなたはそれが本当ではないと知っています。その子はあなたの足音を聞き分けていました。あなたのいちばん苦しかった一年、ずっと足元に寄り添っていました。その子と一緒に消えたのは、毎朝いちばんにあなたを迎えてくれたまなざしでした。</p><p>聖書は実は、動物について多くを語っています。神は動物を造り、養い、彼らと契約を結び、新しくしようとしている世界の中に置かれました。これらのみことばは「すべてのペットが天国にいる」ことを証明はしません。聖書はそう約束していません。けれど、やさしい事実を見せてくれます。<strong>神のご計画の中で、動物は捨ててよい脇役などではなかったのです。</strong></p><p>ここで読むものが、ただのみことばで終わりませんように。雀一羽をも覚えていてくださる神が、あなたのその子も覚えていてくださる、そのことに触れられますように。</p></section><section class="pl-section"><h2>あなたのための4つの読みもの</h2><div class="pl-new-grid"><div class="pl-new-card"><h3><a href="/ja/pets-in-heaven/will-i-see-my-pet-again">また会えるのでしょうか？</a></h3><p>動物と天国の希望について。被造物も共に贖いを待っており、新しい創造にも動物がいます。</p><p class="pl-quote-soft">ローマ人への手紙 8:19-22 · イザヤ書 11:6-9 · ヨハネの黙示録 21:4-5</p></div><div class="pl-new-card"><h3><a href="/ja/pets-in-heaven/not-one-sparrow-forgotten">雀一羽さえ忘れられない</a></h3><p>その子はとても小さかった。世界は覚えていてくれるでしょうか。イエスは、雀一羽さえ父の知らないうちには落ちない、と言われました。</p><p class="pl-quote-soft">マタイの福音書 10:29-31 · 詩篇 147:9 · 詩篇 36:6</p></div><div class="pl-new-card"><h3><a href="/ja/pets-in-heaven/rainbow-bridge-covenant">虹の橋のむこう側</a></h3><p>「虹の橋」は美しい言葉です。そして聖書には本当に虹があります。神が<em>すべての生き物</em>と結ばれた永遠の契約です。</p><p class="pl-quote-soft">創世記 9:9-13 · イザヤ書 65:25 · ヨハネの黙示録 5:13</p></div><div class="pl-new-card"><h3><a href="/ja/pets-in-heaven/permission-to-grieve">悲しんでもいいのです</a></h3><p>あなたの涙を、神は瓶に集めておられます。悲しみは信仰が足りない証拠ではなく、愛が続いていることです。</p><p class="pl-quote-soft">詩篇 56:8 · 詩篇 34:18 · マタイの福音書 5:4</p></div></div></section><section class="pl-section"><h2>読み方のヒント</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🕯️</span><h3>ゆっくり、一度に全部ではなく</h3><p>一段落で十分です。あるみことばで急に涙が出たら、そこで止まってください。弱さではなく、愛が流れているしるしです。</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>みことばにその子の名前を入れて</h3><p>「神は獣に食物を与える」を読むとき、心の中でその子の名前に置きかえてみてください。神はその子もそう顧みてくださいました。</p></div><div class="pl-moment"><span class="pl-moment-icon">🕊️</span><h3>読んだあと、ひとこと伝えて</h3><p>うまくなくて大丈夫です。「会いたいよ」で十分です。もっと書きたくなったら、PetLoss のガイド付きジャーナルが寄り添います。</p></div></div></section><section class="pl-section"><h2>すべての聖句をひとつに</h2><p class="pl-lead">この4つの読みものに出てくる聖句を、ここにまとめました。もう一度ゆっくり読み返し、調べてみてください。</p><div class="pl-verse-groups"><div class="pl-verse-group"><h3><a href="/ja/pets-in-heaven/will-i-see-my-pet-again">また会えるのでしょうか？</a></h3><ul class="pl-verse-list"><li>ローマ人への手紙 8:19-22</li><li>イザヤ書 11:6-9</li><li>ヨハネの黙示録 21:4-5</li><li>詩篇 36:6</li></ul></div><div class="pl-verse-group"><h3><a href="/ja/pets-in-heaven/not-one-sparrow-forgotten">雀一羽さえ忘れられない</a></h3><ul class="pl-verse-list"><li>マタイの福音書 10:29-31</li><li>詩篇 147:9</li><li>詩篇 36:6</li><li>詩篇 50:10-11</li></ul></div><div class="pl-verse-group"><h3><a href="/ja/pets-in-heaven/rainbow-bridge-covenant">虹の橋のむこう側</a></h3><ul class="pl-verse-list"><li>創世記 9:9-13</li><li>イザヤ書 65:25</li><li>ヨハネの黙示録 5:13</li><li>詩篇 150:6</li></ul></div><div class="pl-verse-group"><h3><a href="/ja/pets-in-heaven/permission-to-grieve">悲しんでもいいのです</a></h3><ul class="pl-verse-list"><li>詩篇 56:8</li><li>詩篇 34:18</li><li>詩篇 147:3</li><li>マタイの福音書 5:4</li><li>ヨハネの福音書 11:35</li><li>ヨハネの黙示録 21:4</li></ul></div></div></section><div class="pl-cta"><h2>ここで、そっと抱えてもらえますように。</h2><p>その子の写真を置き、言えなかった言葉を書き留める場所が欲しければ、PetLoss が静かにおそばにいます。アカウント不要、アップロードなし、完全オフライン。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">App Store でダウンロード</a><p class="pl-disclaimer">これらの記事は信仰の黙想と心の寄り添いを提供するもので、医療・心理・カウンセリングの助言ではありません。悲しみが長期にわたり生活を妨げる場合は、有資格の専門家や地域の相談窓口にご相談ください。聖書の引用は欽定訳（KJV）によります。</p></div><div class="pl-bible"><h3>みことばが、これからも寄り添うように</h3><p>この4つの読みものの聖句はすべて聖書から引用しています。虹の聖書ウィジェットなら、いつでも聖書を読み、毎日の聖句ウィジェットを設定できます。会いたい日に、小さな灯りとなりますように。</p><div class="pl-bible-shots"><figure><img src="'+p+'" alt="虹の聖書ウィジェット — 2 テモテ 2:13" loading="lazy"><figcaption>ホーム画面に毎日の聖句</figcaption></figure><figure><img src="'+t+'" alt="虹の聖書 — 天国にいるペット トピック、マタイ 10:29-31" loading="lazy"><figcaption>「天国にいるペット」テーマで聖書を</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">App Storeで虹の聖書ウィジェットを入手</a></div>',7)])])}const g=e(n,[["render",o]]);export{f as __pageData,g as default};
